class Variant(val value: String, val label: String)

private fun toSnakeCase(s: String) = s.replace(Regex("([a-z0-9])([A-Z])"), "$1_$2").lowercase()
private fun humanize(s: String) = toSnakeCase(s).replace('_', ' ').replaceFirstChar { it.uppercase() }

class Field(val property: KProperty1<*, *>) {
    private val input = property.findAnnotation<InputField>()
    private val col = property.findAnnotation<Column>()

    // properties related to the HTML form input
    /**
     * O nome a ser usado no Input HTML
     */
    val name = property.name
    val label = input?.label?.ifBlank { null } ?: humanize(property.name)
    val placeholder = input?.placeholder?.ifBlank { null }
    val footnote = input?.footnote?.ifBlank { null }
    val inputType = input?.type?.ifBlank { null }

    val column = col?.name?.ifBlank { null } ?: toSnakeCase(property.name)
    val unique = col?.unique ?: false
    val isNullable = property.returnType.isMarkedNullable
    val isMultiValued = property.hasAnnotation<Multivalued>()
    val isPk = property.hasAnnotation<PrimaryKey>()
    val autoIncreases = property.findAnnotation<PrimaryKey>()?.autoIncrease ?: false
    val omit = property.hasAnnotation<InputOmit>() || autoIncreases

    // gets either the field's type or the type T from List<T> or any generic stuff
    val type: KClass<*> = if (isMultiValued) {
        require(property.returnType.classifier in setOf(List::class, Set::class)) {
            "@Multivalued em '${property.name}' exige List<T> ou Set<T>"
        }
        property.returnType.arguments.first().type!!.classifier as KClass<*>
    } else property.returnType.classifier as KClass<*>

    init {
        require(!(property.hasAnnotation<Text>() && property.hasAnnotation<VarcharConfig>())) {
            "'${property.name}' não pode ter @Text e @VarcharConfig ao mesmo tempo"
        }

        if (property.hasAnnotation<Text>() || property.hasAnnotation<VarcharConfig>()) {
            require(type == String::class) { "@Text/@VarcharConfig só valem para String ('${property.name}')" }
        }

        if (isMultiValued) require(type.hasAnnotation<ModelEnum>()) {
            "@Multivalued em '${property.name}' exige uma lista (`List` ou `Set`) de @ModelEnum"
        }

        if (property.hasAnnotation<DateTime>()) require(type in setOf(LocalDateTime::class, Instant::class)) {
            "@DateTime só vale para LocalDateTime ou Instant ('${property.name}')"
        }

        if (autoIncreases) require(type == Int::class || type == Long::class) {
            "@PrimaryKey(autoIncrease = true) requer que '${property.name}' seja Int ou Long"
        }
    }
}

object Tucuapi {
    // ===============================================================
    // SQL
    // ===============================================================

    /**
     * Pega todos os campos da classe (na ordem em que foram declarados no construtor).
     */
    private fun getModelFields(model: KClass<*>): List<Field> {
        val constructorOrder = model.primaryConstructor?.parameters?.mapNotNull { it.name }.orEmpty()
        val fieldOrder = model.java.declaredFields.map { it.name }

        fun resolvedPosition(name: String): Int =
            constructorOrder.indexOf(name).takeIf { it >= 0 }
                ?: (constructorOrder.size + fieldOrder.indexOf(name).takeIf { it >= 0 }!!)

        return model.memberProperties
            .filter { it.javaField != null }
            .sortedBy { resolvedPosition(it.name) }
            .map(::Field)
    }

    private fun getTableName(model: KClass<*>): String {
        val modelAnnotation = model.findAnnotation<Model>()
            ?: error("${model.simpleName} não está anotada com @Model e, portanto, não é um modelo válido.");

        return modelAnnotation.table.ifBlank { null }
            ?: model.simpleName?.let { toSnakeCase(it) }
            ?: error("${model.jvmName} não é uma classe nomeada e, portanto, não é elegível para ser um modelo.")
    }

    private fun getEnumVariants(enum: KClass<*>): List<Variant> {
        val variants = enum.java.enumConstants.map { variant ->
            val variantName = (variant as Enum<*>).name
            val annotation = enum.java.getField(variantName).getAnnotation(ModelEnumVariant::class.java)
            val value = annotation?.value?.ifBlank { null } ?: variantName
            val label = annotation?.label?.ifBlank { null } ?: variantName
            Variant(value, label)
        }

        val duplicatedValues = variants.groupBy { it.value }.filterValues { it.size > 1 }.keys
        require(duplicatedValues.isEmpty()) { "O enum ${enum.simpleName} tem valores duplicados: $duplicatedValues" }

        return variants
    }

    private fun getEnumSqlName(enum: KClass<*>): String {
        val enumName = enum.findAnnotation<ModelEnum>()?.name?.ifBlank { null }
            ?: enum.simpleName
            ?: error("O enum ${enum.jvmName} deve possuir um nome e não pode ser um objeto anônimo para ser um enum válido")

        return enumName
    }

    private fun getBaseSqlColumnType(columnKtType: KClass<*>, field: Field): String {
        field.property.findAnnotation<Column>()?.type?.ifBlank { null }?.let { return it }
        return when {
            columnKtType.hasAnnotation<ModelEnum>() -> getEnumSqlName(columnKtType)
            columnKtType == String::class -> "varchar(255)"
            columnKtType == Int::class -> "integer"
            columnKtType == Long::class -> "bigint"
            columnKtType == Double::class -> "double precision"
            columnKtType == Boolean::class -> "boolean"
            columnKtType == LocalDate::class -> "date"
            columnKtType == LocalDateTime::class -> "timestamp"
            columnKtType == Instant::class -> "timestamptz"
            else -> error("Tipo não suportado: ${columnKtType.simpleName}")
        }
    }

    private fun resolveSqlColumnType(field: Field): String {
        field.property.findAnnotation<Text>()?.let { return "text" }
        field.property.findAnnotation<VarcharConfig>()?.let { return "varchar(${it.size})" }
        field.property.findAnnotation<DateTime>()?.let { return if (it.timezoneOffset) "timestamptz" else "timestamp" }
        return getBaseSqlColumnType(field.type, field)
    }

    private fun generateSqlTableStatements(model: KClass<*>): List<String> {
        val tableName = getTableName(model)
        val modelFields = getModelFields(model)
        val primaryKeys = modelFields.filter { it.isPk }

        val columnsStatements = modelFields.filter { !it.isMultiValued }.map { field ->
            buildString {
                append("  ${field.column} ${resolveSqlColumnType(field)}")
                if (!field.isNullable || field.isPk) append(" not null")
                if (field.autoIncreases) append(" generated always as identity")
                if (field.unique) append(" unique")
            }
        }.toMutableList()

        if (primaryKeys.isNotEmpty()) columnsStatements += "  primary key (${primaryKeys.joinToString { it.column }})"

        val wrapperStatement = "create table $tableName (\n${columnsStatements.joinToString(",\n")}\n);"

        val multivaluedTablesStatements = modelFields
            .filter { it.isMultiValued }
            .map { field ->
                require(primaryKeys.isNotEmpty()) { "@Multivalued exige ao menos uma @PrimaryKey em ${model.simpleName}" }
                val foreignKeys = primaryKeys.map { "${tableName}_${it.column}" }
                val linhas = primaryKeys.mapIndexed { i, pk ->
                        "  ${foreignKeys[i]} ${resolveSqlColumnType(pk)} not null" } +
                        "  value ${getBaseSqlColumnType(field.type, field)} not null" +
                        "  primary key (${(foreignKeys + "value").joinToString()})" +
                        "  foreign key (${foreignKeys.joinToString()}) references $tableName (${primaryKeys.joinToString { it.column }})"

                "create table ${tableName}_${field.column} (\n${linhas.joinToString(",\n")}\n);"
            }

        return listOf(wrapperStatement) + multivaluedTablesStatements
    }

    fun generateSqlSetupStatement(vararg models: KClass<*>): String {
        val enums = models
            .flatMap { getModelFields(it) }
            .map { it.type }
            .filter { it.hasAnnotation<ModelEnum>() }
            .distinct()

        val createEnumStatements = enums.map { enum ->
            // (replacing ' with '' escapes simple quotes)
            val variantsStatement = getEnumVariants(enum).joinToString(", ") { "'${it.value.replace("'", "''")}'" }
            val enumName = getEnumSqlName(enum)

            "create type $enumName as enum ($variantsStatement);"
        }

        val setupStatements = createEnumStatements + models.flatMap { generateSqlTableStatements(it) }
        return setupStatements.joinToString("\n\n")
    }

    // ===============================================================
    // HTML
    // ===============================================================

    /**
     * Gera um elemento `select` HTML
     */
    private fun select(field: Field, multiple: Boolean, required: String): String {
        require(field.type.hasAnnotation<ModelEnum>()) { "Campo '${field.name}' precisa ser um @ModelEnum" }

        val options = buildList {
            if (!multiple && field.isNullable) add("  <option value=\"\"></option>")
            getEnumVariants(field.type).forEach { add("  <option value=\"${escape(it.value)}\">${escape(it.label)}</option>") }
        }.joinToString("\n")

        val multipleClause = if (multiple) " multiple" else ""
        return "<select id=\"${field.column}\" name=\"${field.column}\"$multipleClause$required>\n$options\n</select>"
    }

    private fun escape(s: String) = s
        .replace("&", "&amp;").replace("<", "&lt;")
        .replace(">", "&gt;").replace("\"", "&quot;")

    /**
     * Gera um elemento `input` HTML
     */
    private fun input(field: Field): String {
        val requiredClause = if (!field.isNullable && !field.isMultiValued && field.type != Boolean::class) " required" else ""
        val placeholderAttr = field.placeholder?.let { " placeholder=\"${escape(it)}\"" } ?: ""

        val actualInput = when {
            field.isMultiValued -> select(field, true, "")
            field.type.hasAnnotation<ModelEnum>() -> select(field, false, requiredClause)
            field.property.hasAnnotation<Text>() ->
                "<textarea id=\"${field.column}\" name=\"${field.column}\"$placeholderAttr$requiredClause></textarea>"
            else -> {
                val varchar = field.property.findAnnotation<VarcharConfig>()
                val (defaultType, extra) = when {
                    varchar != null -> "text" to " maxlength=\"${varchar.size}\""
                    field.type == String::class -> "text" to " maxlength=\"255\""
                    field.property.hasAnnotation<DateTime>() || field.type == LocalDateTime::class || field.type == Instant::class -> "datetime-local" to ""
                    field.type == Int::class || field.type == Long::class -> "number" to ""
                    field.type == Double::class -> "number" to " step=\"any\""
                    field.type == Boolean::class -> "checkbox" to ""
                    field.type == LocalDate::class -> "date" to ""
                    else -> "text" to ""
                }
                val type = field.inputType ?: defaultType
                "<input type=\"${escape(type)}\" id=\"${field.column}\" name=\"${field.column}\"$extra$placeholderAttr$requiredClause>"
            }
        }
        val footnoteElement = field.footnote?.let { "\n<p>${escape(it)}</p>" } ?: ""
        return "<label for=\"${field.column}\">${escape(field.label)}</label>\n$actualInput$footnoteElement"
    }

    /**
     * Gera um formulário HTML para criar novas instâncias de `model`.
     */
    fun generateHtmlForm(model: KClass<*>, action: String = "/salvar"): String {
        getTableName(model)
        val modelName = model.findAnnotation<Model>()?.title?.ifBlank { null } ?: model.simpleName!!
        val body = getModelFields(model).filter { !it.omit }.joinToString("\n") { "<div>\n${input(it)}\n</div>" }
        return "<h1>Criar ${escape(modelName)}</h1><form method=\"post\" action=\"$action\">\n$body\n<button type=\"submit\">Salvar</button>\n</form>"
    }

    /**
     * Valida os dados enviados pelo formulário
     */
    fun validate(model: KClass<*>, params: Map<String, List<String>>): Map<String, String> =
        getModelFields(model).filter { !it.omit }.mapNotNull { field ->
            val value = params[field.column]?.firstOrNull()
            val error = when {
                field.type == Boolean::class -> null
                !field.isNullable && !field.isMultiValued && value.isNullOrBlank() -> "'${field.label}' é obrigatório."
                value.isNullOrBlank() -> null
                field.type == Int::class && value.toIntOrNull() == null -> "'${field.label}' deve ser inteiro."
                field.type == Long::class && value.toLongOrNull() == null -> "'${field.label}' deve ser inteiro."
                field.type == Double::class && value.toDoubleOrNull() == null -> "'${field.label}' deve ser numérico."
                field.type == String::class && value.length > (field.property.findAnnotation<VarcharConfig>()?.size ?: 255) ->
                    "'${field.label}' excede o tamanho máximo."
                field.type.hasAnnotation<ModelEnum>() && params[field.column].orEmpty()
                    .any { v -> getEnumVariants(field.type).none { it.value == v } } -> "Valor inválido para '${field.label}'."
                else -> null
            }
            error?.let { field.column to it }
        }.toMap()
}